package dev.cmfopen.protocol

import java.io.File
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals

/** Byte-for-byte checks against vectors generated by the Python cmfkit (shared with the web tests). */
class VectorsTest {
    private val json = File(System.getProperty("vectors")).readText()

    private fun str(name: String) = Regex("\"$name\"\\s*:\\s*\"([0-9a-f]*)\"").find(json)!!.groupValues[1]
    private fun list(name: String): List<String> {
        val body = Regex("\"$name\"\\s*:\\s*\\[([^\\]]*)\\]").find(json)!!.groupValues[1]
        return Regex("\"([0-9a-f]+)\"").findAll(body).map { it.groupValues[1] }.toList()
    }

    private val key = Bytes.fromHex(str("key"))
    private fun fill(b: Int) = ByteArray(16) { b.toByte() }

    @Test fun derivesTheSameKeys() {
        assertEquals(str("authkey"), Bytes.hex(Crypto.deriveAuthkey(fill(1), fill(2), fill(3))))
        assertEquals(str("sessionKey"), Bytes.hex(Crypto.deriveSessionKey(fill(4), key)))
        assertEquals(str("sign"), Bytes.hex(Crypto.sign(fill(1), fill(3))))
        assertEquals(str("crc"), Bytes.hex(Crypto.crc32le("cmfkit".toByteArray())))
    }

    @Test fun buildsTheSamePayloads() {
        assertEquals(str("notification"), Bytes.hex(Payloads.notification("Hi", "from cmfkit ✓", Payloads.Icons.GENERIC, 1_700_000_000)))
        assertEquals(str("music"), Bytes.hex(Payloads.musicInfo("Focus 24:59", "Pomodoro - 0 done", Payloads.MUSIC_PAUSED)))
        assertEquals(str("weather"), Bytes.hex(Payloads.weather("Lisbon", 21)))
        assertEquals(
            str("contacts"),
            Bytes.hex(Payloads.contacts(listOf(Payloads.Contact("Lap 1", "00:42"), Payloads.Contact("Ä long name ".repeat(4), "x")))),
        )
        assertEquals(str("timeSync"), Bytes.hex(Payloads.timeSync(1_700_000_000, 3600)))
        assertEquals(str("photoInit"), Bytes.hex(Payloads.photoDialInit(12345, 2, 56, 77, 0xF800)))
    }

    @Test fun encodesIdenticalFrames() {
        assertEquals(list("musicFrames"), Frame.encode(Ops.MUSIC_INFO_SET, Bytes.fromHex(str("music")), key, 64).map(Bytes::hex))
        val plain = ByteArray(200) { it.toByte() }
        assertEquals(list("plainFrames"), Frame.encode(Ops.WF_CHUNK_WRITE, plain, key, 64).map(Bytes::hex))
    }

    @Test fun decodesSplitFramesAndWatchStylePlaintext() {
        val dec = FrameDecoder(plaintextCrcOnWire = true).also { it.key = key }
        val wire = Bytes.fromHex(list("musicFrames").joinToString(""))
        val out = dec.feed(wire.copyOfRange(0, 7)) + dec.feed(wire.copyOfRange(7, wire.size))
        assertEquals(1, out.size)
        assertEquals(Payloads.MusicInfo(1, "Focus 24:59", "Pomodoro - 0 done"), Payloads.parseMusicInfo(out[0].payload))

        val watch = FrameDecoder(plaintextCrcOnWire = false)
        val reply = watch.feed(Bytes.fromHex(list("watchFrames").joinToString(""))).single()
        assertContentEquals(ByteArray(48), reply.payload)
    }
}
